-- TitikTemu migration file. Do not edit after it has been applied to a shared database.
-- For future changes, create a new numbered file (example: 003_add_column_x.sql).

-- ============================================================================
-- TITIKTEMU - FULL DATABASE SCHEMA (PostgreSQL)
-- Jalankan hanya pada database development BARU yang masih kosong.
-- Jangan jalankan pada database yang sudah berisi data, karena tabelnya akan
-- bertabrakan. Untuk database Day 1/Day 2 yang sudah ada, baca 04_upgrade_day2.sql.
-- ============================================================================
CREATE TABLE kategori (
  id_kategori INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama_kategori VARCHAR(50) NOT NULL UNIQUE,
  deskripsi TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Data lokasi master hanya digunakan untuk mengatur letak pos penyerahan.
-- Lokasi kejadian dalam form laporan adalah teks bebas, bukan dropdown.
CREATE TABLE lokasi (
  id_lokasi INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama_lokasi VARCHAR(100) NOT NULL UNIQUE,
  deskripsi TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE pos_penyerahan (
  id_pos INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama_pos VARCHAR(100) NOT NULL,
  jenis_pos VARCHAR(30) NOT NULL CHECK (jenis_pos IN ('pos_keamanan','ruang_administrasi','lainnya')),
  id_lokasi INTEGER NOT NULL REFERENCES lokasi(id_lokasi) ON DELETE RESTRICT,
  detail_lokasi VARCHAR(150),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_pos_nama_lokasi UNIQUE (nama_pos, id_lokasi)
);

CREATE TABLE pengguna (
  id_pengguna INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nim VARCHAR(20) UNIQUE,
  username VARCHAR(50),
  password_hash VARCHAR(255) NOT NULL,
  nama VARCHAR(100) NOT NULL,
  email VARCHAR(254),
  email_verified_at TIMESTAMPTZ,
  no_hp VARCHAR(20),
  prodi VARCHAR(100),
  role VARCHAR(20) NOT NULL CHECK (role IN ('mahasiswa','petugas','admin')),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  last_login TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_pengguna_identitas CHECK (
    (role = 'mahasiswa' AND nim IS NOT NULL AND username IS NULL)
    OR (role IN ('petugas','admin') AND username IS NOT NULL AND nim IS NULL)
  ),
  CONSTRAINT chk_nim_format CHECK (role <> 'mahasiswa' OR nim ~ '^[0-9]{8,20}$'),
  CONSTRAINT chk_staff_username_format CHECK (role NOT IN ('petugas','admin') OR username ~ '^[A-Za-z][A-Za-z0-9._-]{3,49}$')
);
CREATE UNIQUE INDEX uq_pengguna_username_lower ON pengguna (LOWER(username)) WHERE username IS NOT NULL;
CREATE UNIQUE INDEX uq_pengguna_email_lower ON pengguna (LOWER(email)) WHERE email IS NOT NULL;
CREATE INDEX idx_pengguna_role ON pengguna(role);
CREATE INDEX idx_pengguna_active_role ON pengguna(is_active, role);
CREATE INDEX idx_pengguna_last_login ON pengguna(last_login DESC) WHERE role = 'mahasiswa';
COMMENT ON COLUMN pengguna.no_hp IS 'Data privat, tidak ditampilkan di halaman publik.';
COMMENT ON COLUMN pengguna.email_verified_at IS 'Disiapkan untuk kebutuhan verifikasi email pada pengembangan berikutnya.';

CREATE TABLE pengumuman (
  id_pengumuman INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_pengguna INTEGER NOT NULL REFERENCES pengguna(id_pengguna) ON DELETE RESTRICT,
  id_kategori INTEGER NOT NULL REFERENCES kategori(id_kategori) ON DELETE RESTRICT,
  -- Lokasi master tidak dipilih pada form kejadian. Kolom id_lokasi disimpan
  -- nullable untuk migrasi/kompatibilitas dan keperluan filter internal lama.
  id_lokasi INTEGER REFERENCES lokasi(id_lokasi) ON DELETE SET NULL,
  id_pos INTEGER REFERENCES pos_penyerahan(id_pos) ON DELETE RESTRICT,
  jenis VARCHAR(10) NOT NULL CHECK (jenis IN ('hilang','temuan')),
  judul VARCHAR(150) NOT NULL,
  deskripsi TEXT NOT NULL,
  email_kontak VARCHAR(254) NOT NULL,
  lokasi_kejadian VARCHAR(200) NOT NULL,
  tanggal_waktu_kejadian TIMESTAMPTZ NOT NULL,
  detail_lokasi VARCHAR(200),
  status VARCHAR(20) NOT NULL DEFAULT 'menunggu',
  id_verifikator INTEGER REFERENCES pengguna(id_pengguna) ON DELETE SET NULL,
  catatan_verifikasi TEXT,
  tanggal_verifikasi TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_pengumuman_status_jenis CHECK (
    (jenis = 'hilang' AND status IN ('menunggu','aktif','selesai','ditolak','ditutup'))
    OR (jenis = 'temuan' AND status IN ('menunggu','tersedia','diproses','selesai','ditolak','ditutup'))
  ),
  CONSTRAINT chk_pos_hanya_untuk_temuan CHECK (
    (jenis = 'hilang' AND id_pos IS NULL) OR (jenis = 'temuan' AND id_pos IS NOT NULL)
  ),
  CONSTRAINT chk_email_kontak_format CHECK (email_kontak ~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$')
);
CREATE INDEX idx_pengumuman_jenis_status_tanggal ON pengumuman(jenis,status,tanggal_waktu_kejadian DESC);
CREATE INDEX idx_pengumuman_pengguna ON pengumuman(id_pengguna);
CREATE INDEX idx_pengumuman_kategori ON pengumuman(id_kategori);
CREATE INDEX idx_pengumuman_lokasi_text ON pengumuman(LOWER(lokasi_kejadian));
COMMENT ON TABLE pengumuman IS 'Satu tabel untuk laporan kehilangan dan barang temuan; form juga satu form.';
COMMENT ON COLUMN pengumuman.status IS 'menunggu berarti belum publik; hanya laporan yang disetujui staf yang ditampilkan ke publik.';
COMMENT ON COLUMN pengumuman.email_kontak IS 'Kontak privat untuk notifikasi; jangan ditampilkan pada halaman umum.';
COMMENT ON COLUMN pengumuman.lokasi_kejadian IS 'Teks bebas yang ditulis pengguna, bukan dropdown master.';

CREATE TABLE foto_pengumuman (
  id_foto INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_pengumuman INTEGER NOT NULL REFERENCES pengumuman(id_pengumuman) ON DELETE CASCADE,
  bucket_name VARCHAR(100) NOT NULL,
  file_path VARCHAR(255) NOT NULL,
  nama_file VARCHAR(255),
  mime_type VARCHAR(100) NOT NULL,
  ukuran_byte BIGINT NOT NULL CHECK (ukuran_byte > 0),
  urutan SMALLINT NOT NULL DEFAULT 1 CHECK (urutan BETWEEN 1 AND 3),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_foto_urutan UNIQUE(id_pengumuman,urutan)
);
CREATE INDEX idx_foto_pengumuman ON foto_pengumuman(id_pengumuman);
COMMENT ON TABLE foto_pengumuman IS 'Metadata foto. File fisik disimpan di storage di luar public/.';

CREATE TABLE klaim (
  id_klaim INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_pengumuman INTEGER NOT NULL REFERENCES pengumuman(id_pengumuman) ON DELETE RESTRICT,
  id_pengguna INTEGER NOT NULL REFERENCES pengguna(id_pengguna) ON DELETE RESTRICT,
  id_petugas INTEGER REFERENCES pengguna(id_pengguna) ON DELETE SET NULL,
  deskripsi_bukti TEXT NOT NULL,
  bukti_path VARCHAR(255),
  status_verifikasi VARCHAR(20) NOT NULL DEFAULT 'menunggu'
    CHECK (status_verifikasi IN ('menunggu','disetujui','ditolak','dibatalkan')),
  tanggal_pengajuan TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  tanggal_verifikasi TIMESTAMPTZ,
  catatan_verifikasi TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_klaim_pengumuman ON klaim(id_pengumuman);
CREATE INDEX idx_klaim_pengguna ON klaim(id_pengguna);
CREATE INDEX idx_klaim_status ON klaim(status_verifikasi);
CREATE UNIQUE INDEX uq_klaim_aktif_pengguna_barang
 ON klaim(id_pengumuman,id_pengguna)
 WHERE status_verifikasi IN ('menunggu','disetujui');
CREATE UNIQUE INDEX uq_klaim_disetujui_per_barang
 ON klaim(id_pengumuman) WHERE status_verifikasi='disetujui';

CREATE TABLE kecocokan (
  id_kecocokan INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_pengumuman_hilang INTEGER NOT NULL REFERENCES pengumuman(id_pengumuman) ON DELETE RESTRICT,
  id_pengumuman_temuan INTEGER NOT NULL REFERENCES pengumuman(id_pengumuman) ON DELETE RESTRICT,
  skor_kecocokan NUMERIC(5,2) CHECK (skor_kecocokan IS NULL OR skor_kecocokan BETWEEN 0 AND 100),
  status_kecocokan VARCHAR(25) NOT NULL DEFAULT 'menunggu_review'
    CHECK (status_kecocokan IN ('menunggu_review','kemungkinan_cocok','tidak_cocok','ditindaklanjuti','selesai')),
  id_peninjau INTEGER REFERENCES pengguna(id_pengguna) ON DELETE SET NULL,
  catatan_admin TEXT,
  ditinjau_pada TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_pasangan_laporan_berbeda CHECK(id_pengumuman_hilang<>id_pengumuman_temuan),
  CONSTRAINT uq_pasangan_kecocokan UNIQUE(id_pengumuman_hilang,id_pengumuman_temuan)
);
CREATE INDEX idx_kecocokan_status ON kecocokan(status_kecocokan);

CREATE TABLE riwayat_status_pengumuman (
  id_riwayat INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_pengumuman INTEGER NOT NULL REFERENCES pengumuman(id_pengumuman) ON DELETE RESTRICT,
  status_sebelumnya VARCHAR(20),
  status_baru VARCHAR(20) NOT NULL,
  id_pengubah INTEGER REFERENCES pengguna(id_pengguna) ON DELETE SET NULL,
  catatan TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_riwayat_status_baru CHECK(status_baru IN ('menunggu','aktif','tersedia','diproses','selesai','ditolak','ditutup')),
  CONSTRAINT chk_riwayat_status_lama CHECK(status_sebelumnya IS NULL OR status_sebelumnya IN ('menunggu','aktif','tersedia','diproses','selesai','ditolak','ditutup'))
);
CREATE INDEX idx_riwayat_pengumuman_tanggal ON riwayat_status_pengumuman(id_pengumuman,created_at DESC);

CREATE TABLE notifikasi_email (
  id_notifikasi INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_kecocokan INTEGER NOT NULL REFERENCES kecocokan(id_kecocokan) ON DELETE RESTRICT,
  id_penerima INTEGER NOT NULL REFERENCES pengguna(id_pengguna) ON DELETE RESTRICT,
  jenis_notifikasi VARCHAR(40) NOT NULL CHECK(jenis_notifikasi IN ('kemungkinan_barang_ditemukan')),
  email_tujuan VARCHAR(254) NOT NULL,
  subjek VARCHAR(200) NOT NULL,
  isi_email TEXT NOT NULL,
  status_kirim VARCHAR(20) NOT NULL DEFAULT 'menunggu' CHECK(status_kirim IN ('menunggu','terkirim','gagal')),
  jumlah_percobaan SMALLINT NOT NULL DEFAULT 0 CHECK(jumlah_percobaan>=0),
  error_terakhir TEXT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  terkirim_pada TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_notifikasi_match_penerima_jenis UNIQUE(id_kecocokan,id_penerima,jenis_notifikasi)
);
CREATE INDEX idx_notifikasi_status_tanggal ON notifikasi_email(status_kirim,dibuat_pada);

-- Generic update timestamp trigger.
CREATE OR REPLACE FUNCTION fn_set_updated_at() RETURNS TRIGGER AS $$
BEGIN NEW.updated_at=NOW(); RETURN NEW; END;
$$ LANGUAGE plpgsql;
DO $$
DECLARE t TEXT;
BEGIN
 FOREACH t IN ARRAY ARRAY['kategori','lokasi','pos_penyerahan','pengguna','pengumuman','klaim','kecocokan','notifikasi_email'] LOOP
   EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I','trg_'||t||'_updated_at',t);
   EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at()','trg_'||t||'_updated_at',t);
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION fn_validasi_klaim() RETURNS TRIGGER AS $$
DECLARE v_jenis TEXT; v_status TEXT; v_pemilik INTEGER; v_role TEXT;
BEGIN
 SELECT jenis,status,id_pengguna INTO v_jenis,v_status,v_pemilik FROM pengumuman WHERE id_pengumuman=NEW.id_pengumuman FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Laporan yang akan diklaim tidak ditemukan.'; END IF;
 IF v_jenis <> 'temuan' THEN RAISE EXCEPTION 'Klaim hanya dapat diajukan untuk laporan barang temuan.'; END IF;
 IF v_status <> 'tersedia' THEN RAISE EXCEPTION 'Barang temuan belum tersedia untuk diklaim.'; END IF;
 IF v_pemilik = NEW.id_pengguna THEN RAISE EXCEPTION 'Pelapor barang temuan tidak dapat mengklaim laporannya sendiri.'; END IF;
 SELECT role INTO v_role FROM pengguna WHERE id_pengguna=NEW.id_pengguna;
 IF v_role IS DISTINCT FROM 'mahasiswa' THEN RAISE EXCEPTION 'Hanya mahasiswa yang dapat mengajukan klaim.'; END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_validasi_klaim_insert BEFORE INSERT ON klaim FOR EACH ROW EXECUTE FUNCTION fn_validasi_klaim();
CREATE TRIGGER trg_validasi_klaim_update BEFORE UPDATE OF id_pengumuman,id_pengguna ON klaim FOR EACH ROW EXECUTE FUNCTION fn_validasi_klaim();

CREATE OR REPLACE FUNCTION fn_validasi_kecocokan() RETURNS TRIGGER AS $$
DECLARE j1 TEXT; j2 TEXT; role_reviewer TEXT;
BEGIN
 SELECT jenis INTO j1 FROM pengumuman WHERE id_pengumuman=NEW.id_pengumuman_hilang;
 SELECT jenis INTO j2 FROM pengumuman WHERE id_pengumuman=NEW.id_pengumuman_temuan;
 IF j1 IS DISTINCT FROM 'hilang' THEN RAISE EXCEPTION 'Pasangan pertama harus laporan kehilangan.'; END IF;
 IF j2 IS DISTINCT FROM 'temuan' THEN RAISE EXCEPTION 'Pasangan kedua harus barang temuan.'; END IF;
 IF NEW.id_peninjau IS NOT NULL THEN
  SELECT role INTO role_reviewer FROM pengguna WHERE id_pengguna=NEW.id_peninjau;
  IF role_reviewer IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Peninjau kecocokan harus admin.'; END IF;
 END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_validasi_kecocokan_insert BEFORE INSERT ON kecocokan FOR EACH ROW EXECUTE FUNCTION fn_validasi_kecocokan();
CREATE TRIGGER trg_validasi_kecocokan_update BEFORE UPDATE OF id_pengumuman_hilang,id_pengumuman_temuan,id_peninjau ON kecocokan FOR EACH ROW EXECUTE FUNCTION fn_validasi_kecocokan();

CREATE OR REPLACE FUNCTION fn_validasi_staff_laporan() RETURNS TRIGGER AS $$
DECLARE v_role TEXT;
BEGIN
 IF NEW.id_verifikator IS NULL THEN RETURN NEW; END IF;
 SELECT role INTO v_role FROM pengguna WHERE id_pengguna=NEW.id_verifikator;
 IF v_role NOT IN ('petugas','admin') OR v_role IS NULL THEN RAISE EXCEPTION 'Verifikator harus petugas atau admin.'; END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_validasi_staff_laporan_insert BEFORE INSERT ON pengumuman FOR EACH ROW EXECUTE FUNCTION fn_validasi_staff_laporan();
CREATE TRIGGER trg_validasi_staff_laporan_update BEFORE UPDATE OF id_verifikator ON pengumuman FOR EACH ROW EXECUTE FUNCTION fn_validasi_staff_laporan();

CREATE OR REPLACE FUNCTION fn_validasi_staff_klaim() RETURNS TRIGGER AS $$
DECLARE v_role TEXT;
BEGIN
 IF NEW.id_petugas IS NULL THEN RETURN NEW; END IF;
 SELECT role INTO v_role FROM pengguna WHERE id_pengguna=NEW.id_petugas;
 IF v_role NOT IN ('petugas','admin') OR v_role IS NULL THEN RAISE EXCEPTION 'Pemeriksa klaim harus petugas atau admin.'; END IF;
 RETURN NEW;
END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_validasi_staff_klaim_insert BEFORE INSERT ON klaim FOR EACH ROW EXECUTE FUNCTION fn_validasi_staff_klaim();
CREATE TRIGGER trg_validasi_staff_klaim_update BEFORE UPDATE OF id_petugas ON klaim FOR EACH ROW EXECUTE FUNCTION fn_validasi_staff_klaim();

-- Kandidat tidak pernah otomatis dianggap milik seseorang. Admin harus meninjau.
CREATE OR REPLACE VIEW v_kandidat_kecocokan AS
SELECT h.id_pengumuman AS id_pengumuman_hilang, h.judul AS judul_laporan_hilang,
       h.deskripsi AS deskripsi_hilang, h.lokasi_kejadian AS lokasi_hilang,
       h.tanggal_waktu_kejadian AS waktu_hilang, h.id_pengguna AS id_pemilik_laporan_hilang,
       ph.nama AS nama_pelapor_hilang, th.id_pengumuman AS id_pengumuman_temuan,
       th.judul AS judul_laporan_temuan, th.deskripsi AS deskripsi_temuan,
       th.lokasi_kejadian AS lokasi_temuan, th.tanggal_waktu_kejadian AS waktu_temuan,
       th.id_pengguna AS id_pelapor_temuan, pt.nama AS nama_pelapor_temuan,
       k.nama_kategori, hf.id_foto AS foto_hilang, tf.id_foto AS foto_temuan,
       CASE WHEN LOWER(TRIM(h.judul))=LOWER(TRIM(th.judul)) THEN 1 ELSE 0 END AS judul_sama,
       CASE WHEN LOWER(TRIM(h.lokasi_kejadian))=LOWER(TRIM(th.lokasi_kejadian)) THEN 1 ELSE 0 END AS lokasi_sama,
       ABS(DATE(th.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')-DATE(h.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')) AS selisih_hari,
       (40
        + CASE WHEN LOWER(TRIM(h.judul))=LOWER(TRIM(th.judul)) THEN 30 ELSE 0 END
        + CASE WHEN LOWER(TRIM(h.lokasi_kejadian))=LOWER(TRIM(th.lokasi_kejadian)) THEN 20 ELSE 0 END
        + CASE
            WHEN ABS(DATE(th.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')-DATE(h.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')) <= 1 THEN 10
            WHEN ABS(DATE(th.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')-DATE(h.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')) <= 7 THEN 7
            ELSE 4
          END
       ) AS skor_kandidat
FROM pengumuman h
JOIN pengumuman th ON th.id_kategori=h.id_kategori
JOIN pengguna ph ON ph.id_pengguna=h.id_pengguna
JOIN pengguna pt ON pt.id_pengguna=th.id_pengguna
JOIN kategori k ON k.id_kategori=h.id_kategori
LEFT JOIN LATERAL (
  SELECT fp.id_foto FROM foto_pengumuman fp WHERE fp.id_pengumuman=h.id_pengumuman ORDER BY fp.urutan LIMIT 1
) hf ON TRUE
LEFT JOIN LATERAL (
  SELECT fp.id_foto FROM foto_pengumuman fp WHERE fp.id_pengumuman=th.id_pengumuman ORDER BY fp.urutan LIMIT 1
) tf ON TRUE
WHERE h.jenis='hilang' AND h.status='aktif'
  AND th.jenis='temuan' AND th.status='tersedia'
  AND h.id_pengguna<>th.id_pengguna
  -- Tanggal kejadian bisa tercatat sebelum atau sesudah laporan dibuat, jadi jendelanya simetris.
  AND ABS(DATE(th.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')-DATE(h.tanggal_waktu_kejadian AT TIME ZONE 'Asia/Jakarta')) <= 30
  AND NOT EXISTS (SELECT 1 FROM kecocokan c WHERE c.id_pengumuman_hilang=h.id_pengumuman AND c.id_pengumuman_temuan=th.id_pengumuman);
COMMENT ON VIEW v_kandidat_kecocokan IS 'Kandidat berdasarkan kategori dan waktu, diurutkan dengan skor petunjuk sederhana dari judul/lokasi/tanggal; skor bukan probabilitas dan admin wajib meninjau.';

